using System;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BottledAuroraOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/BottledAurora Omen Data")]
public class BottledAuroraOmenData : OmenData
{
	private const string atTheEndOfDrawPhaseID = "AtTheEndOfDrawPhase";

	[Header("Multiverse Cube")]
	[SerializeField]
	private GameObject bottledAuroraOmenCanvasPrefab;

	[SerializeField]
	private VoidEvent OnShowBottledAuroraCanvas;

	[SerializeField]
	private CameraReference mainCameraReference;

	[NonSerialized]
	private GameObject bottledAuroraOmenCanvasGameObject;

	[NonSerialized]
	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		AlreadyUsed = false;
		bottledAuroraOmenCanvasGameObject = UnityEngine.Object.Instantiate(bottledAuroraOmenCanvasPrefab);
		bottledAuroraOmenCanvasGameObject.GetComponent<Canvas>().worldCamera = mainCameraReference.value;
		ReferenceSingleton<MiscOmensHandler>.Instance.BottledAuroraOmenData = this;
		this.omenInstance = omenInstance;
	}

	public void BottledAuroraOmenAction()
	{
		omenInstance.ActivateOmenFeedback();
		OnShowBottledAuroraCanvas.Raise();
		AlreadyUsed = true;
	}

	public override void OmenRemoved()
	{
		UnityEngine.Object.Destroy(bottledAuroraOmenCanvasGameObject);
		bottledAuroraOmenCanvasGameObject = null;
		ReferenceSingleton<MiscOmensHandler>.Instance.BottledAuroraOmenData = null;
	}

	public override string OmenConvertedDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("AtTheEndOfDrawPhase") + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + base.OmenConvertedDescription();
	}
}
